mapper.select:
SELECT GROUP_SEQ AS groupSeq, GROUP_NAME AS groupName, USE_YN AS useYn FROM UI_KEYWORD_GROUP WHERE 1=1
AND GROUP_NAME LIKE CONCAT('%', #{searchStr}, '%')
AND USE_YN = #{useYn}
ORDER BY GROUP_SEQ
LIMIT ${offset}, ${limit}

SELECT  COUNT(*) AS CNT
FROM	UI_KEYWORD_GROUP
WHERE	GROUP_NAME = #{groupName}

	AND		GROUP_SEQ != #{groupSeq}

mapper.update:
UPDATE	UI_KEYWORD_GROUP
SET		GROUP_NAME 	= #{groupName},
USE_YN 		= #{useYn}
WHERE	GROUP_SEQ 	= #{groupSeq}

mapper.select:
SELECT A.GROUP_SEQ AS groupSeq, A.GROUP_NAME AS groupName, B.KEYWORD_SEQ AS keywordSeq, B.KEYWORD_NAME AS keywordName, B.KEYWORD_DESC AS keywordDesc FROM UI_KEYWORD_GROUP A, UI_KEYWORD B WHERE A.GROUP_SEQ = B.GROUP_SEQ
AND B.KEYWORD_NAME LIKE CONCAT('%', #{searchStr}, '%')
AND B.GROUP_SEQ = ${searchGroupSeq}
ORDER BY B.KEYWORD_SEQ
LIMIT ${offset}, ${limit}

SELECT  COUNT(*) AS CNT
FROM	UI_KEYWORD
WHERE	KEYWORD_NAME = #{keywordName}

	AND		KEYWORD_SEQ != #{keywordSeq}

mapper.update:
UPDATE	UI_KEYWORD
SET		KEYWORD_NAME 	= #{keywordName},
KEYWORD_DESC 	= #{keywordDesc}
WHERE	KEYWORD_SEQ 	= #{keywordSeq}
